import { describe, it, expect } from "vitest";
import openapi from "../openapi.json";

// This test catches drift between the hand-written path unions in
// `src/lib/api-routes.ts` and the actual OpenAPI spec generated by the huma
// backend. A mismatch here means the server has removed or renamed a path
// that the frontend still relies on.
//
// During the huma migration many endpoints are still raw-gin and therefore
// don't appear in the spec — we spot-check only endpoints that ARE migrated
// so the test stays green while still catching server-side changes that
// break known-migrated flows.
//
// Mapping rules (hand-written → generated):
//   - `api-client.ts` prepends `/api` to every hand-written path
//   - hand-written uses template literals like `/games/${string}` which we
//     translate to `/api/games/{param}` by replacing `${string}` with a
//     placeholder segment. `{param}` also replaces whatever placeholder
//     name the spec uses (`{id}`, `{gameId}`, ...) so the shapes compare
//     symbol-free.

type OpenAPISpec = {
  paths: Record<string, Record<string, unknown>>;
};

const spec = openapi as unknown as OpenAPISpec;

function normalizeHandWritten(path: string): string {
  const withoutQuery = path.split("?")[0];
  return "/api" + withoutQuery.replace(/\$\{string\}/g, "{param}");
}

function normalizeGenerated(path: string): string {
  return path.replace(/\{[^}]+\}/g, "{param}");
}

function generatedPatterns(): Set<string> {
  const out = new Set<string>();
  for (const p of Object.keys(spec.paths)) {
    out.add(normalizeGenerated(p));
  }
  return out;
}

describe("generated OpenAPI spec", () => {
  it("is a well-formed object with a paths map", () => {
    expect(spec).toBeTypeOf("object");
    expect(spec.paths).toBeTypeOf("object");
    expect(Object.keys(spec.paths).length).toBeGreaterThan(0);
  });

  it("exposes the canonical /api/health endpoint", () => {
    // Sanity: the health endpoint is the first huma migration and must exist.
    expect(spec.paths["/api/health"]).toBeDefined();
  });

  it("has every path under the /api prefix", () => {
    // Every huma-registered path starts with /api. If this ever fails the
    // server has registered a route outside the /api namespace and the
    // api-client.ts `/api` prefix assumption breaks.
    const offenders: string[] = [];
    for (const p of Object.keys(spec.paths)) {
      if (!p.startsWith("/api/")) offenders.push(p);
    }
    expect(offenders).toEqual([]);
  });
});

describe("hand-written path unions drift check", () => {
  // A representative sample of hand-written paths pulled from api-routes.ts,
  // limited to endpoints already migrated to huma (i.e. present in the spec).
  //
  // If any of these disappear from the OpenAPI spec, the drift test catches
  // it before the feature breaks at runtime. Expand this list as more
  // endpoints migrate off raw gin.
  const migratedHandWrittenPaths = [
    "/health",
    "/search",
    "/consoles",
    "/games",
    `/games/${"${string}"}`,
    `/games/${"${string}"}/ratings`,
    "/user/profile",
    "/user/preferences",
    "/user/favorites",
    "/user/devices",
    "/bios",
    "/cores",
    "/admin/users",
    "/admin/settings",
    "/admin/stats",
    "/admin/system-events",
    "/netplay/sessions",
    "/challenges",
    "/collections",
    "/shared-sessions",
  ];

  const generated = generatedPatterns();

  for (const raw of migratedHandWrittenPaths) {
    it(`has a matching generated path for ${raw}`, () => {
      const normalized = normalizeHandWritten(raw);
      expect(generated, `expected ${normalized} to exist in generated spec`).toContain(normalized);
    });
  }
});
